const skinMap=canvasTex((g,s)=>{g.fillStyle='#e2a091';g.fillRect(0,0,s,s);for(let i=0;i<900;i++){const r=4+Math.random()*26,x=Math.random()*s,y=Math.random()*s;g.fillStyle=`rgba(${190+Math.random()*50|0},${120+Math.random()*45|0},${110+Math.random()*40|0},${.025+Math.random()*.05})`;g.beginPath();g.arc(x,y,r,0,7);g.fill()}for(let i=0;i<6500;i++){g.fillStyle=`rgba(${Math.random()>.5?'255,215,198':'123,70,66'},${.035+Math.random()*.08})`;g.fillRect(Math.random()*s,Math.random()*s,1+Math.random()*2,1+Math.random()*2)}},512,2);
